INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-23', 'es', 'LAIKA 64 3.5: lista nueva y lobby al instante', 'Nuevo modo lista con el juego de fondo y su logo, carátula propia desde tus unidades, lo más jugado en línea, la versión de cada hack en el lobby, Discord en Comunidad y el lobby se actualiza al instante. Corregido el cierre al salir de Juegos. Actualiza desde LAIKA.'),
 ('2026-11-23', 'en', 'LAIKA 64 3.5: new list and instant lobby', 'A new list view with the game behind and its logo, your own box art from your drives, the most played games online, each hack''s version in the lobby, Discord in Community and a lobby that updates at once. Fixed the crash leaving Games. Update from LAIKA.'),
 ('2026-11-23', 'pt', 'LAIKA 64 3.5: lista nova e lobby na hora', 'Novo modo lista com o jogo ao fundo e seu logo, capa própria das suas unidades, os mais jogados online, a versão de cada hack no lobby, Discord em Comunidade e o lobby se atualiza na hora. Corrigido o fechamento ao sair de Jogos. Atualize pelo LAIKA.'),
 ('2026-11-23', 'fr', 'LAIKA 64 3.5 : nouvelle liste et salon instantané', 'Nouvelle vue liste avec le jeu en fond et son logo, jaquette perso depuis vos lecteurs, les plus joués en ligne, la version de chaque hack dans le salon, Discord dans Communauté et un salon mis à jour aussitôt. Plantage en quittant Jeux corrigé. Mettez à jour depuis LAIKA.'),
 ('2026-11-23', 'it', 'LAIKA 64 3.5: nuova lista e lobby istantanea', 'Nuova vista elenco con il gioco sullo sfondo e il logo, copertina tua dalle tue unità, i più giocati online, la versione di ogni hack nella lobby, Discord in Community e la lobby si aggiorna subito. Corretto il crash uscendo da Giochi. Aggiorna da LAIKA.'),
 ('2026-11-23', 'de', 'LAIKA 64 3.5: neue Liste und sofortige Lobby', 'Neue Listenansicht mit dem Spiel im Hintergrund und Logo, eigenes Cover von deinen Laufwerken, die meistgespielten Spiele online, die Version jedes Hacks in der Lobby, Discord in Community und eine sofort aktualisierte Lobby. Absturz beim Verlassen von Spiele behoben. Aktualisiere über LAIKA.'),
 ('2026-11-23', 'ru', 'LAIKA 64 3.5: новый список и мгновенное лобби', 'Новый вид списка с игрой на фоне и её логотипом, своя обложка с ваших дисков, самые популярные игры в сети, версия каждого хака в лобби, Discord в Сообществе и мгновенно обновляемое лобби. Исправлен вылет при выходе из Игр. Обновитесь через LAIKA.');
